mapper.update:
update outtaskitem
outtaskid = #{outtaskid}, outbillid = #{outbillid}, outorderid = #{outorderid}, hintsite = #{hintsite}, hintbatchno = #{hintbatchno}, sn = #{sn}, hintqty = #{hintqty}, outdesc = #{outdesc}, dataversion = #{dataversion}, data1 = #{data1}, data2 = #{data2}, data3 = #{data3}, data4 = #{data4}, data5 = #{data5}, data6 = #{data6}, data7 = #{data7}, data8 = #{data8}, materialid = #{materialid}, collectedqty = #{collectedqty}, collecter = #{collecter}, outstate = #{outstate}, collect_date = #{collectDate}, repertoryid = #{repertoryid}, occupyqty = #{occupyqty}, occupyflag = #{occupyflag}, subinventory_code = #{subinventoryCode}, hintfinish = #{hintfinish}, palletno = #{palletno}, productline = #{productline}, workstation = #{workstation}, agvstate = #{agvstate}, beatflag = #{beatflag},
where outtaskitemid = #{outtaskitemid}

mapper.select:
select distinct onf.outproofno as taskcomment, onf.orderno, onf.po_number, oi.palletno, sts.storesiteno, o.outtaskno, 1 as hintqty, GetPalletNumByTaskId(o.outtaskid,oi.palletno) as hintfinish, GetPalletStatusByOutTaskItemId(oi.outtaskid,oi.palletno) palletStatus, nvl(g.workStation,'N') as workStation from outtask o, outtaskitem oi, pm_material pm, storeroom str, storesite sts, outbill g, outproof onf where o.outtaskid=oi.outtaskid and oi.materialid=pm.pm_materialid and o.storeroomid = str.storeroomid and oi.hintsite = sts.storesiteid and oi.outstate = 1 and oi.outbillid = g.outbillid and g.OUTPROOFID = onf.OUTPROOFID and nvl(oi.hintfinish,0) = 0 and nvl(g.hintfinish,0) = 0 and (nvl(oi.hintqty,0)-nvl(oi.collectedqty,0))> 0
and o.outtaskno = #{outtaskno} and str.roomtag = #{roomTag} and oi.collecter = #{collecter} and nvl(g.workstation,'N')= #{workstation}
order by oi.palletno,sts.storesiteno
